#include <iostream>
#include <sstream>
#include <string>
#include <iomanip>
#include <vector>

std::string fila(const std::string& etiqueta, int cantidad) {
    std::ostringstream texto;
    texto << "[" << std::left << std::setfill(' ') << std::setw(6) << etiqueta
        << "]|[" << std::right << std::setw(3) << cantidad << "]";
    return texto.str();
}

int main() {
    std::cout << fila("Sol", 4) << "\n" << fila("Couloir", 1000) << "\n" << fila("", 0);
    return 0;
}

